mkdir -p /travail/Atm.Tests && cd /travail/Atm.Tests && cat > TestKit.cs <<'EOF'
namespace Atm.Tests;

/// <summary>Petits outils partagés : construire un scénario, l'exécuter, lire le résultat.</summary>
internal static class TestKit
{
    public static NoteCounts N(int fifties, int twenties, int tens) => new(fifties, twenties, tens);

    /// <summary>0 = aucune cassette bloquée, sinon 50, 20 ou 10.</summary>
    public static Denomination? Jam(int jammed) => jammed == 0 ? null : (Denomination)jammed;

    public static AccountState Acc(int balance, int withdrawnToday) => new(balance, withdrawnToday);

    public static (AtmResult Result, MoneyDispenser Dispenser) Withdraw(
        int balance, int withdrawnToday, NoteCounts stock, Denomination? jammed, int amount)
    {
        var dispenser = new MoneyDispenser(stock, jammed);
        var result = new CashMachine(dispenser).Execute(Acc(balance, withdrawnToday), new Operation.Withdraw(amount));
        return (result, dispenser);
    }

    public static (AtmResult Result, MoneyDispenser Dispenser) Deposit(
        int balance, int withdrawnToday, NoteCounts stock, Denomination? jammed, NoteCounts notes)
    {
        var dispenser = new MoneyDispenser(stock, jammed);
        var result = new CashMachine(dispenser).Execute(Acc(balance, withdrawnToday), new Operation.Deposit(notes));
        return (result, dispenser);
    }

    /// <summary>Un refus : rien ne change, ni le compte, ni les billets.</summary>
    public static void AssertRefused(
        AtmStatus expected, AtmResult result, AccountState before, MoneyDispenser dispenser, NoteCounts stockBefore)
    {
        Assert.Equal(expected, result.Status);
        Assert.Equal(NoteCounts.None, result.Notes);
        Assert.Equal(0, result.Fee);
        Assert.Equal(before, result.Account);
        Assert.Equal(stockBefore, dispenser.Stock);
    }
}
EOF
cat > SpecExamplesTests.cs <<'EOF'
using static Atm.Tests.TestKit;

namespace Atm.Tests;

/// <summary>Le tableau « Exemples » de la spec, ligne par ligne, vérifié en entier.</summary>
public class SpecExamplesTests
{
    [Theory]
    // solde, retiré, stock (50,20,10), bloquée, montant | statut, billets (50,20,10), frais, solde, retiré
    [InlineData(100, 0, 1, 3, 0, 0, 60, AtmStatus.Ok, 0, 3, 0, 0, 40, 60)]
    [InlineData(100, 0, 1, 1, 1, 0, 80, AtmStatus.Ok, 1, 1, 1, 0, 20, 80)]
    [InlineData(105, 0, 5, 5, 5, 0, 100, AtmStatus.Ok, 2, 0, 0, 0, 5, 100)]
    [InlineData(115, 0, 5, 5, 5, 0, 110, AtmStatus.Ok, 2, 0, 1, 5, 0, 110)]
    [InlineData(110, 0, 5, 5, 5, 0, 110, AtmStatus.InsufficientFunds, 0, 0, 0, 0, 110, 0)]
    [InlineData(250, 150, 5, 5, 5, 0, 60, AtmStatus.DailyLimitExceeded, 0, 0, 0, 0, 250, 150)]
    [InlineData(250, 0, 1, 0, 0, 50, 50, AtmStatus.CannotDispense, 0, 0, 0, 0, 250, 0)]
    [InlineData(250, 0, 2, 2, 0, 50, 40, AtmStatus.Ok, 0, 2, 0, 0, 210, 40)]
    [InlineData(0, 200, 0, 0, 0, 0, 5, AtmStatus.InvalidAmount, 0, 0, 0, 0, 0, 200)]
    public void Withdrawal_examples(
        int balance, int withdrawn, int s50, int s20, int s10, int jammed, int amount,
        AtmStatus status, int n50, int n20, int n10, int fee, int balanceAfter, int withdrawnAfter)
    {
        var stock = N(s50, s20, s10);
        var notes = N(n50, n20, n10);

        var (result, dispenser) = Withdraw(balance, withdrawn, stock, Jam(jammed), amount);

        Assert.Equal(status, result.Status);
        Assert.Equal(notes, result.Notes);
        Assert.Equal(fee, result.Fee);
        Assert.Equal(Acc(balanceAfter, withdrawnAfter), result.Account);
        Assert.Equal(stock - notes, dispenser.Stock);
    }

    [Theory]
    // solde, retiré, stock, bloquée, dépôt | statut, stock après, solde, retiré
    [InlineData(10, 0, 0, 5, 0, 0, 0, 1, 0, AtmStatus.CassetteFull, 0, 5, 0, 10, 0)]
    [InlineData(10, 30, 0, 1, 0, 20, 0, 1, 0, AtmStatus.CassetteJammed, 0, 1, 0, 10, 30)]
    [InlineData(10, 30, 1, 1, 0, 0, 1, 0, 1, AtmStatus.Ok, 2, 1, 1, 70, 30)]
    public void Deposit_examples(
        int balance, int withdrawn, int s50, int s20, int s10, int jammed, int d50, int d20, int d10,
        AtmStatus status, int a50, int a20, int a10, int balanceAfter, int withdrawnAfter)
    {
        var (result, dispenser) = Deposit(balance, withdrawn, N(s50, s20, s10), Jam(jammed), N(d50, d20, d10));

        Assert.Equal(status, result.Status);
        Assert.Equal(NoteCounts.None, result.Notes);
        Assert.Equal(0, result.Fee);
        Assert.Equal(Acc(balanceAfter, withdrawnAfter), result.Account);
        Assert.Equal(N(a50, a20, a10), dispenser.Stock);
    }
}
