 'failures.Check($"solde {balance}, retiré {withdrawn}, stock {Show(stock)}, bloquée {jam?.ToString() ?? "aucune"}, Retrait {amount}",')
s=s.replace('failures.Check($"{acc} stock={stock} bloquée={jam?.ToString() ?? "aucune"} Dépôt {notes}",',
 'failures.Check($"solde {balance}, retiré {withdrawn}, stock {Show(stock)}, bloquée {jam?.ToString() ?? "aucune"}, Dépôt {Show(notes)}",')
# varier le compte en dernier masque la diversité des cas : on parcourt le compte en premier
s=s.replace('''        foreach (var stock in Stocks())
            foreach (var jam in Jams)
                foreach (var amount in Amounts)
                    foreach (var balance in Balances)
                        foreach (var withdrawn in WithdrawnValues)''','''        foreach (var balance in Balances.Reverse())
            foreach (var withdrawn in WithdrawnValues)
                foreach (var amount in Amounts)
                    foreach (var jam in Jams)
                        foreach (var stock in Stocks())''')
open(p,'w').write(s)
EOF
